#!/usr/bin/env python3
from pathlib import Path
import base64
import hashlib
import shutil

ROOT = Path.cwd()
MIDI_DIR = ROOT / "sound/songs/midi"

FILES = {
    "mus_meet_me_halfway.mid": """""",
    "mus_where_is_the_love.mid": """""",
}

EXPECTED = {
    "mus_meet_me_halfway.mid": "50855465749ed006666ad879704e2bb6cb018b50ebb99546e2e857ad4859803f",
    "mus_where_is_the_love.mid": "bba2e0ca2797929365c8af22a5518ea168c27dcd8c43975ad8d7cc1144955bcc",
}

if not (ROOT / "include/constants/songs.h").exists() or not MIDI_DIR.exists():
    raise SystemExit("ERRO: rode este Python na raiz do pokeemerald-expansion.")

for name, payload in FILES.items():
    dst = MIDI_DIR / name
    if dst.exists():
        backup = dst.with_name(dst.name + ".before_bep_fix_v3")
        if not backup.exists():
            shutil.copyfile(dst, backup)
            backup.touch()
            print("[BACKUP]", backup)

    data = base64.b64decode(payload)
    if hashlib.sha256(data).hexdigest() != EXPECTED[name]:
        raise SystemExit("ERRO INTERNO: hash invalido para " + name)

    dst.write_bytes(data)
    dst.touch()
    print("[WRITE]", dst)

    stem = dst.stem
    asm = MIDI_DIR / (stem + ".s")
    if asm.exists():
        asm.unlink()
        print("[DELETE]", asm)

    for obj in ROOT.glob("build/*/sound/songs/midi/" + stem + ".o"):
        obj.unlink()
        print("[DELETE]", obj)

print()
print("[OK] BLACK EYED PEAS - BEP FIX V3 instalado")
print("Meet Me Halfway: pulse guitar -> soft rhythm/bass, intro sem silencio")
print("Where Is the Love: lead suavizado + cabasa 69 removida, intro sem silencio")
print()
print("Agora rode:")
print("  make -j9")
